import {skipToken} from '@reduxjs/toolkit/query'

import {useAppSelector} from '../../../../hooks/react-redux'
import {restApi} from '../../../../services/rest'
import type {BuildTypeId} from '../../../../types'
import {extractText, getDslOptions, getDslRequestEndpoint} from '../Dsl.selectors'
import DslEditor from '../DslEditor/DslEditor'

export type BuildTypeDslEditorProps = {
  controlId: string
  buildTypeOrTemplateId: BuildTypeId
  currentStage?: string | null | undefined
}
const INDENT = '    '

export default function BuildTypeDslEditor(props: BuildTypeDslEditorProps) {
  const {buildTypeOrTemplateId, controlId, currentStage} = props
  const dslEndpoint = useAppSelector(state =>
    getDslRequestEndpoint(state, buildTypeOrTemplateId, controlId),
  )
  const show = useAppSelector(state => getDslOptions(state, controlId)?.show ?? false)
  const {data} = restApi.endpoints.getHtml.useQuery(
    show ? {path: dslEndpoint, method: 'POST'} : skipToken,
    {selectFromResult: ({data}) => ({data})},
  )
  const error = extractText(data, 'error')
  let entity = error == null ? extractText(data, 'entityData') : null
  let before = error == null ? extractText(data, 'beforeData') : null
  let after = error == null ? extractText(data, 'afterData') : null

  if (currentStage != null && entity != null && before == null && after == null) {
    const startMarker = `\n${INDENT}${currentStage} {`
    const endMarker = `\n${INDENT}}`
    const i1 = entity.indexOf(startMarker)
    const i2 = entity.indexOf(`${endMarker}`, i1)

    if (i1 > -1 && i2 > i1) {
      before = entity.substring(0, i1 - 1)
      after = entity.substring(i2 + endMarker.length + 1)
      entity = entity.substring(i1, i2 + endMarker.length)
    }
  }

  return (
    <DslEditor
      {...props}
      show={show}
      error={error}
      entity={entity}
      before={before}
      after={after}
      hasCurrentStage={currentStage != null}
    />
  )
}
