import Code from '@jetbrains/ring-ui-built/components/code/code'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import CopyIconButton from '../../../common/CopyIconButton/CopyIconButton'
import Loader from '../../../common/Loader/Loader'

import {LEARN_KOTLIN_DSL_LINK} from './DslEditor.consts'
import DslOptions from './DslOptions/DslOptions.container'

import styles from './DslEditor.module.css'

type DefaultProps = {
  entityOnly: boolean
  hasCurrentStage: boolean
}
type Props = DefaultProps & {
  before?: string | null | undefined
  entity: string | null | undefined
  after?: string | null | undefined
  error?: string | null | undefined
  show: boolean
  currentZindex?: number | null | undefined
  controlId: string
}

class DslEditor extends React.PureComponent<Props> {
  static defaultProps: DefaultProps = {
    entityOnly: false,
    hasCurrentStage: false,
  }

  entityRef = React.createRef<HTMLElement>()
  firstTimeScrolled = false

  shouldShowCodeSection: (arg0: Props) => boolean = props =>
    this.entityRef.current != null &&
    props.hasCurrentStage &&
    props.show &&
    props.entity != null &&
    props.before != null &&
    !this.firstTimeScrolled

  generateTextForClipboard: () => string = () => {
    const {before, entity, after, entityOnly} = this.props
    return entityOnly ? `${entity || ''}` : `${before || ''}${entity || ''}${after || ''}`
  }

  componentDidUpdate(prevProps: Props) {
    const {show} = this.props

    if (!prevProps.show && show) {
      this.firstTimeScrolled = false
    }

    if (!this.shouldShowCodeSection(prevProps) && this.shouldShowCodeSection(this.props)) {
      this.entityRef.current?.scrollIntoView()
      this.firstTimeScrolled = true
    }
  }

  render(): React.ReactNode {
    const {
      entity,
      error,
      before,
      after,
      show,
      entityOnly,
      currentZindex,
      controlId,
      hasCurrentStage,
    } = this.props

    if (!show) {
      return null
    }

    if (show && error == null && entity == null && before == null && after == null) {
      return <Loader />
    }

    const text = this.generateTextForClipboard()
    const beforeClasses = classNames(styles.codeWrapper, styles.white)
    const entityClasses = classNames(
      styles.codeWrapper,
      before != null ? styles.blue : styles.white,
      !entityOnly && before != null && !hasCurrentStage ? styles.additionalIndent : '',
      !entityOnly && before != null && hasCurrentStage ? styles.smallIndent : '',
    )
    return (
      <div>
        <div className={styles.optionsBox}>
          {error == null && (
            <CopyIconButton
              iconClassName={styles.iconButton}
              wrapperClassName={styles.iconWrapper}
              text={text}
              beforeCopyContent={'Copy to clipboard'}
              afterCopyContent={'Copied to clipboard'}
            />
          )}
          <IconButton
            className={styles.iconButton}
            icon="new-window"
            target="_blank"
            href={LEARN_KOTLIN_DSL_LINK}
            rel="noreferrer"
          >
            {'Learn Kotlin DSL'}
          </IconButton>
          <DslOptions currentZindex={currentZindex} controlId={controlId} />
        </div>
        <div className={styles.codeSection}>
          {error != null && (
            <div
              className={styles.error}
            >{`An error occurred during DSL generation: ${error}`}</div>
          )}
          {error == null && !entityOnly && before != null && (
            <Code language="kotlin" code={before} className={beforeClasses} />
          )}
          {error == null && entity != null && (
            <Code
              language="kotlin"
              codeRef={this.entityRef}
              code={entity}
              className={entityClasses}
            />
          )}
          {error == null && !entityOnly && after != null && (
            <Code language="kotlin" code={after} className={beforeClasses} />
          )}
        </div>
      </div>
    )
  }
}

export default DslEditor
