import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import Select from '@jetbrains/ring-ui-built/components/select/select'

import {restApi} from '../../../../../services/rest'
import type {DslOption} from '../../../../../types'

import styles from './DslOptions.module.css'

const Z_INDEX_INCREMENT = 5
type Props = {
  portable?: boolean
  version: string
  onVersionChanged: (version: string) => unknown
  onPortableChanged: (portable: boolean) => unknown
  currentZindex?: number | null | undefined
  availableDslOptions?: ReadonlyArray<DslOption> | null | undefined
}

const getLabel = (version: string): string =>
  `Version ${version.replace(/^v/, '').replace(/_/g, '.')}`

type VersionChange = {
  key: string
  label: string
}

function DslOptionsComponent(props: Props) {
  const {availableDslOptions} = restApi.endpoints.getDslOptions.useQuery(undefined, {
    selectFromResult: ({data}) => ({availableDslOptions: data?.kotlin}),
  })

  const handleVersionChange: (arg0: VersionChange | null) => void = selected => {
    if (selected && props.version !== selected.key) {
      props.onVersionChanged(selected.key)
    }
  }

  const handlePortableChange: () => void = () => {
    props.onPortableChanged(!props.portable)
  }

  const {version, portable, currentZindex} = props

  if (!availableDslOptions) {
    return null
  }

  const data = availableDslOptions.map(ver => ({
    label: getLabel(ver.version),
    key: ver.version,
  }))
  const selected = version ? data.find(ver => ver.key === version) : null
  const popupStyle =
    currentZindex != null
      ? {
          zIndex: currentZindex + Z_INDEX_INCREMENT,
        }
      : undefined
  const portables = availableDslOptions.filter(ver => ver.portable).map(ver => ver.version)
  return (
    <div className={styles.dslOptions}>
      <Select
        type={Select.Type.INLINE}
        label="Choose a version"
        selected={selected}
        data={data}
        className={styles.select}
        onSelect={handleVersionChange}
        popupStyle={popupStyle}
      />
      {selected && portables.includes(selected.key) && (
        <Checkbox checked={portable} label="Portable" onChange={handlePortableChange} />
      )}
    </div>
  )
}

export default DslOptionsComponent
