import {withHandlers} from 'recompose'

import compose from 'lodash/flowRight'
import {connect} from 'react-redux'

import type {State} from '../../../../../reducers/types'
import {setDslPortable, setDslVersion} from '../../Dsl.actions'
import {getDslOptions} from '../../Dsl.selectors'

import DslOptionsComponent from './DslOptions'

type Props = {
  controlId: string
  currentZindex?: number | null | undefined
}

const mapStateToProps = (state: State, props: Props) => getDslOptions(state, props.controlId) ?? {}

type ActionProps = {
  switchDslVersion: (controlId: string, version: string) => unknown
  switchPortable: (controlId: string, portable: boolean) => unknown
}
const actionCreators = {
  switchDslVersion: setDslVersion,
  switchPortable: setDslPortable,
}
export default compose(
  connect(mapStateToProps, actionCreators),
  withHandlers({
    onVersionChanged:
      ({switchDslVersion, controlId}: Props & ActionProps) =>
      (version: string) => {
        switchDslVersion(controlId, version)
      },
    onPortableChanged:
      ({switchPortable, controlId}: Props & ActionProps) =>
      (portable: boolean) => {
        switchPortable(controlId, portable)
      },
  }),
)(DslOptionsComponent)
